#!/usr/bin/env python3
"""Verify pinned Git blobs and generate verbatim Rust slices, never a selector port."""
import argparse, hashlib, importlib.util, json, pathlib
ROOT=pathlib.Path(__file__).resolve().parent

def load_cases():
    spec=importlib.util.spec_from_file_location('synthetic_cases',ROOT/'fixtures/build_cases.py')
    module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module)
    return module.build()

def render_module(revision):
    name=revision['name']
    lines=(ROOT/'sources'/name/'community_release.rs').read_bytes().splitlines(keepends=True)
    output=f'''// Generated by verify_sources.py from unchanged upstream lines.
// Commit: {revision['commit']}
use anyhow::{{Context, Result}};
use semver::Version;
use serde::Deserialize;
#[path = "../sources/{name}/product.rs"]
mod xai_grok_product;
'''.encode()
    if name=='current_msvc':
        output += b"\nuse std::collections::{HashMap, HashSet};\nuse std::fs::{File, OpenOptions};\nuse std::io::{Read, Seek, Write};\nuse std::path::Path;\nuse sha2::{Digest, Sha256};\n#[path = \"../sources/current_msvc/package_protocol.rs\"]\nmod package_protocol;\n#[path = \"../sources/current_msvc/embedded_runtime.rs\"]\nmod embedded_runtime;\nuse package_protocol::{BUILD_INFO, PackageProtocol};\n"
    for start,end in revision['unchanged_ranges']:
        output+=f'\n// Verbatim community_release.rs:L{start}-L{end}\n'.encode()+b''.join(lines[start-1:end])
    # Handwritten adapter: parse synthetic inputs, dispatch exact production functions,
    # and report observed output. No policy logic is replaced or reimplemented.
    output+=b'\n// Harness-only adapter begins. Selection policy above is unchanged.\n'
    output+=b'''pub(crate) fn observe(case: &serde_json::Value) -> Result<super::Observation> {
    let releases: Vec<ApiRelease> = serde_json::from_value(case["releases"].clone())?;
    let platform = match case["platform"].as_str().context("fixture platform missing")? {
'''
    for platform in revision['platforms']:
        output+=f'        "{platform}" => CommunityPlatform::{platform},\n'.encode()
    output+=b'''        other => anyhow::bail!("unsupported fixture platform: {other}"),
    };
    let asset = if case["mode"] == "asset" {
        select_asset_for_platform(
            releases.first().context("fixture requires one release")?,
            case["requested_version"].as_str().context("fixture version missing")?,
            platform,
        )?
    } else {
        let (release, version) = select_latest_compatible_release(
            &releases,
            case["channel"].as_str().context("fixture channel missing")?,
            platform,
        )?;
        select_asset_for_platform(release, &version.to_string(), platform)?
    };
    Ok(super::Observation {
        version: asset.version,
        asset_name: asset.name,
'''
    output+=b'        target_platform: Some(format!("{:?}", asset.target_platform)),\n' if name=='current_msvc' else b'        target_platform: None,\n'
    output+=b'    })\n}\n'
    if name=='current_msvc':
        output += b'\n#[cfg(test)]\n#[path = "current_extraction_tests.rs"]\nmod extraction_tests;\n'
    return output

def render_tests(cases):
    output='''// Generated case names only; each test executes unchanged source through a narrow adapter.
use serde_json::Value;

fn run_case(id: &str) {
    let matrix: Value = serde_json::from_str(include_str!("../fixtures/selection-matrix.json")).unwrap();
    assert_eq!(matrix["fixture_kind"], "SYNTHETIC_OFFLINE_API_METADATA");
    let case = matrix["cases"].as_array().unwrap().iter().find(|case| case["id"] == id).unwrap();
    let observed = match case["revision"].as_str().unwrap() {
        "v1_0_8" => super::v1_0_8::observe(case),
        "v1_0_45" => super::v1_0_45::observe(case),
        "current_msvc" => super::current_msvc::observe(case),
        other => panic!("unrecognized revision: {other}"),
    };
    let expected = &case["expect"];
    if let Some(fragment) = expected["error_contains"].as_str() {
        let error = observed.expect_err(id).to_string();
        assert!(error.contains(fragment), "{id}: expected error containing {fragment:?}, got {error:?}");
    } else {
        let observed = observed.unwrap_or_else(|error| panic!("{id}: {error:#}"));
        assert_eq!(observed.version, expected["version"].as_str().unwrap(), "{id}: version");
        assert_eq!(observed.asset_name, expected["asset_name"].as_str().unwrap(), "{id}: asset");
        if case["revision"] == "current_msvc" {
            assert_eq!(observed.target_platform.as_deref(), case["platform"].as_str(), "{id}: requesting ABI preserved");
        }
    }
}
'''
    for case in cases['cases']:
        id=case['id'];assert all(c.isalnum() or c=='_' for c in id)
        output+=f'\n#[test]\nfn {id}() {{ run_case("{id}"); }}\n'
    return output.encode()

def main():
    parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');args=parser.parse_args()
    provenance=json.loads((ROOT/'source-provenance.json').read_text())
    report={'scope':provenance['scope'],'source_checks':[],'generated_checks':[],'rust_execution':'NOT EXECUTED by this provenance/static preflight checker'}
    for revision in provenance['revisions']:
        for f in revision['files']:
            data=(ROOT/f['path']).read_bytes()
            blob=hashlib.sha1(b'blob '+str(len(data)).encode()+b'\0'+data).hexdigest()
            assert blob==f['git_blob_sha1'],f"Git blob mismatch: {f['path']}"
            digest=hashlib.sha256(data).hexdigest()
            assert digest==f['sha256'] and len(data)==f['bytes'],f"SHA/size mismatch: {f['path']}"
            report['source_checks'].append({'path':f['path'],'commit':revision['commit'],'git_blob_sha1':blob,'sha256':digest,'compiled':f['compiled'],'result':'PASS'})
        target=ROOT/'src'/f"{revision['name']}.rs";generated=render_module(revision)
        if args.check: assert target.read_bytes()==generated,f'Generated source mismatch: {target}'
        else:target.write_bytes(generated)
        report['generated_checks'].append({'path':str(target.relative_to(ROOT)),'sha256':hashlib.sha256(generated).hexdigest(),'verbatim_ranges':revision['unchanged_ranges'],'result':'PASS'})
    cases=load_cases();fixture=(json.dumps(cases,indent=2)+'\n').encode();tests=render_tests(cases)
    for relative,data in [('fixtures/selection-matrix.json',fixture),('src/matrix_tests.rs',tests)]:
        path=ROOT/relative
        if args.check:assert path.read_bytes()==data,f'Generated fixture/test mismatch: {relative}'
        else:path.write_bytes(data)
        report['generated_checks'].append({'path':relative,'sha256':hashlib.sha256(data).hexdigest(),'result':'PASS'})
    authored=ROOT/'src/current_extraction_tests.rs'
    report['authored_current_extraction_tests_sha256']=hashlib.sha256(authored.read_bytes()).hexdigest()
    report['required_current_extraction_assertions']=4
    report['synthetic_matrix_cases']=len(cases['cases'])
    report['cases_per_revision']={r['name']:sum(c['revision']==r['name'] for c in cases['cases']) for r in provenance['revisions']}
    (ROOT/'results').mkdir(exist_ok=True)
    (ROOT/'results/source-provenance-check.json').write_text(json.dumps(report,indent=2)+'\n')
    print(f"PASS: {len(report['source_checks'])} pinned Git blobs, 3 verbatim source modules, {report['synthetic_matrix_cases']} synthetic case definitions; Rust not executed")
if __name__=='__main__':main()
